import{_ as t,c as i,o as r,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"ADDRESSING CERTAIN TARIFFS ON IMPORTED ARTICLES","description":"","frontmatter":{"title":"ADDRESSING CERTAIN TARIFFS ON IMPORTED ARTICLES","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/addressing-certain-tariffs-on-imported-articles/","publishDate":"2025-04-29T16:23:14-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-29-addressing-certain-tariffs-on-imported-articles.md","filePath":"executive-orders/2025-04-29-addressing-certain-tariffs-on-imported-articles.md"}'),s={name:"executive-orders/2025-04-29-addressing-certain-tariffs-on-imported-articles.md"};function o(n,e,l,d,c,p){return r(),i("div",null,e[0]||(e[0]=[a('<h1 id="addressing-certain-tariffs-on-imported-articles" tabindex="-1">ADDRESSING CERTAIN TARIFFS ON IMPORTED ARTICLES <a class="header-anchor" href="#addressing-certain-tariffs-on-imported-articles" aria-label="Permalink to &quot;ADDRESSING CERTAIN TARIFFS ON IMPORTED ARTICLES&quot;">​</a></h1><p>Published: Tuesday, April 29, 2025</p><ul><li><p><strong>Authority</strong>: Executive order issued under various U.S. laws including the International Emergency Economic Powers Act and the National Emergencies Act.</p></li><li><p><strong>Tariffs Purpose</strong>: Acknowledges existing tariffs aimed at protecting national security and addressing threats to the U.S. economy and foreign policy.</p></li><li><p><strong>Cumulative Effect</strong>: The order states that overlapping tariffs on the same article should not cumulatively apply to avoid excessive duty rates.</p></li><li><p><strong>Tariff Application</strong>:</p><ul><li>Only applies to specified actions affecting tariffs.</li><li>Details the hierarchy for applying tariffs when an article is subject to multiple tariff actions: <ul><li>Actions regarding automobiles and parts.</li><li>Actions addressing illicit drug flow at the northern and southern borders.</li><li>Proclamations adjusting imports of aluminum and steel.</li></ul></li></ul></li><li><p><strong>Specific Guidelines</strong>:</p><ul><li>Tariffs from one action can negate additional tariffs from others under specific conditions.</li><li>Tariffs from actions not listed are still cumulative with tariffs outlined in this order.</li></ul></li><li><p><strong>Non-Impact on Other Duties</strong>: The order does not affect other duties, taxes, or fees that may still apply to affected articles.</p></li><li><p><strong>Implementation Responsibilities</strong>:</p><ul><li>The Secretary of Homeland Security, in coordination with other departments, will update guidance and systems to align with this order.</li><li>Changes to the Harmonized Tariff Schedule (HTSUS) should be completed by May 16, 2025, and will be retroactively applied.</li></ul></li><li><p><strong>Legal Provisions</strong>: The order does not modify the authority of executive departments and does not grant enforceable rights against the United States or its entities.</p></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/addressing-certain-tariffs-on-imported-articles/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/addressing-certain-tariffs-on-imported-articles/</a></p>',4)]))}const h=t(s,[["render",o]]);export{u as __pageData,h as default};
